      const html = await response.text();
      const decodeEntities = (s) => s.replace(/&nbsp;/gi, " ").replace(/&deg;/gi, "\xB0").replace(/&ordm;/gi, "\xB0").replace(/&amp;/gi, "&").replace(/&aacute;/gi, "\xE1").replace(/&eacute;/gi, "\xE9").replace(/&iacute;/gi, "\xED").replace(/&oacute;/gi, "\xF3").replace(/&uacute;/gi, "\xFA").replace(/&ntilde;/gi, "\xF1").replace(/&Aacute;/g, "\xC1").replace(/&Eacute;/g, "\xC9").replace(/&Iacute;/g, "\xCD").replace(/&Oacute;/g, "\xD3").replace(/&Uacute;/g, "\xDA").replace(/&Ntilde;/g, "\xD1").replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10))).replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'");
