          titulo: decodeEntities(cells[boletinIdx + 1] || "Proyecto de ley"),
          ley: cells[boletinIdx + 2] || "",
          estado: cells[boletinIdx + 3] || "En tramitaci\xF3n",
          fecha: parseFechaChilena(cells[boletinIdx + 4] || "")
