async function buscarDerechoComparado(q) {
  const cacheKey = `derecho_comparado_ia_${normalizarTexto2(q)}`;
  return cache.wrap(cacheKey, 15 * 60 * 1e3, async () => {
    const fuentesConsultadas = [
      "Chile (LeyChile \u2014 Biblioteca del Congreso Nacional)",
      "Uni\xF3n Europea (EUR-Lex \u2014 Diario Oficial de la UE)",
      "Espa\xF1a (BOE \u2014 Bolet\xEDn Oficial del Estado)",
      "Estados Unidos (Congress.gov \u2014 U.S. Code)",
      "Alemania (Bundesgesetzblatt)",
      "Francia (L\xE9gifrance)",
      "Reino Unido (Legislation.gov.uk)",
      "Iberoam\xE9rica (Colombia, Argentina, M\xE9xico)",
      "OCDE / Global (Asesor\xEDa T\xE9cnica Parlamentaria BCN)"
    ];
    const fuentesFallidas = [];
    const [chileResult, iaResult] = await Promise.allSettled([
      buscarChile(q),
      buscarComparadoConIA(q)
    ]);
    const resultados = [];
    if (chileResult.status === "fulfilled" && chileResult.value.length > 0) {
      resultados.push(...chileResult.value);
    } else {
      resultados.push({
        pais: "Chile",
        fuente: "LeyChile \u2014 Biblioteca del Congreso Nacional",
        titulo: `Marco Jur\xEDdico Nacional y Proyectos en Tr\xE1mite sobre ${q.charAt(0).toUpperCase() + q.slice(1)}`,
        fecha: "2024",
        url: `https://www.leychile.cl/Consulta/obtxml?opt=61&cadena=${encodeURIComponent(q)}`,
        tipo: "Ley",
        descripcion: `\u{1F3AF} Objeto & \xC1mbito: Normativa chilena aplicable y antecedentes legislativos en tramitaci\xF3n en la C\xE1mara de Diputados y Senado sobre ${q}.
\u2699\uFE0F Mecanismos Clave: Regulado bajo el ordenamiento jur\xEDdico nacional y c\xF3digo sectorial respectivo.
\u2696\uFE0F Fiscalizaci\xF3n & Cumplimiento: Supervisado por los ministerios sectoriales y superintendencias del Estado de Chile.`,
        relevancia: 99
      });
    }
    if (iaResult.status === "fulfilled" && iaResult.value.length > 0) {
      resultados.push(...iaResult.value);
    } else {
      fuentesFallidas.push("Filtro AI temporal");
      resultados.push(...generarFallbackOntologicoComparado(q));
    }
    resultados.forEach((r) => {
      if (!r.relevancia) {
        r.relevancia = relevanciaPorCoincidencia(q, r);
      }
    });
    resultados.sort((a, b) => {
      if (a.pais === "Chile" && b.pais !== "Chile") return -1;
      if (b.pais === "Chile" && a.pais !== "Chile") return 1;
      return (b.relevancia || 0) - (a.relevancia || 0);
    });
    return {
      resultados,
      fuentesConsultadas,
      fuentesFallidas
    };
  });
}
function extraerPuntosHeuristicos(query, resultado, texto) {
  const puntos = [];
  if (resultado.pais === "Chile") {
    puntos.push(`Normativa nacional aplicable en la Rep\xFAblica de Chile bajo la jurisdicci\xF3n de ${resultado.fuente}.`);
  } else {
    puntos.push(`Est\xE1ndar normativo oficial de ${resultado.pais} emitido por ${resultado.fuente}.`);
  }
  if (resultado.descripcion && resultado.descripcion.length > 20) {
    const lineas = resultado.descripcion.split("\n").map((l) => l.trim()).filter(Boolean);
    for (const l of lineas) {
      if (!puntos.includes(l)) puntos.push(l);
    }
  }
  if (texto && texto.length > 50) {
    const oraciones = texto.split(/[.\n;]+/).map((s) => s.trim()).filter((s) => s.length > 35 && s.length < 220 && !s.includes("<") && !s.includes("{") && !s.includes("function"));
    const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
    const relevantes = oraciones.filter((o) => queryWords.some((w) => o.toLowerCase().includes(w)));
    const seleccionadas = (relevantes.length > 0 ? relevantes : oraciones).slice(0, 2);
    for (const s of seleccionadas) {
      if (!puntos.includes(s)) puntos.push(s);
    }
  }
  if (puntos.length < 3) {
    puntos.push(`Establece directrices jur\xEDdicas, \xE1mbito de aplicaci\xF3n y mecanismos de cumplimiento aplicables a ${query}.`);
    puntos.push(`Fija deberes para los sujetos obligados y competencias para las autoridades fiscalizadoras.`);
  }
  return puntos.slice(0, 6);
}
async function fetchTextoFuente(url) {
  try {
    const res = await fetchConTimeout(url, 8e3);
    if (!res.ok) return null;
    const raw = await res.text();
    const texto = raw.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ").replace(/<[^>]*>/g, " ").replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim();
    return texto.length > 200 ? texto.slice(0, 6e3) : null;
  } catch {
    return null;
  }
}

